1	// Animated inline text swap: when the label changes, the old text fades/slides
2	// out and the new one slides in (e.g. "Change" → "Saving…" → "Saved",
3	// "Copy" → "Copied!"). Respects reduced motion. Zero layout opinion — the
4	// parent keeps its own sizing, so reserve space for the widest state there if
5	// shifts matter. Callers who need a different feel (or none at all) don't
6	// touch this file — see `transition`/`variants`/`disabled` below.
7	import { AnimatePresence, motion, useReducedMotion, type Transition, type TargetAndTransition } from "framer-motion";
8	import type { ReactNode } from "react";
9	
10	/** The baseline distance/duration/ease, exported so a caller building a custom
11	 *  `transition` or `variants` can start from the same values instead of guessing. */
12	// eslint-disable-next-line react-refresh/only-export-components
13	export const SWAP_TEXT_DEFAULTS = { distance: 5, duration: 0.18, ease: "easeOut" as const };
14	
15	interface SwapTextVariants {
16	  initial?: TargetAndTransition;
17	  animate?: TargetAndTransition;
18	  exit?: TargetAndTransition;
19	}
20	
21	interface SwapTextProps {
22	  children: ReactNode;
23	  /** Identifies the current state; the swap animates when it changes.
24	      Defaults to the children themselves when they are a string/number. */
25	  swapKey?: string | number;
26	  /** Vertical travel in px of the outgoing/incoming text (ignored if `variants` is given). */
27	  distance?: number;
28	  /** Duration in seconds, used only when `transition` is not given. */
29	  duration?: number;
30	  /** Replaces the default `{ duration, ease: "easeOut" }` transition entirely — tune ease, duration or use a spring. */
31	  transition?: Transition;
32	  /** Opt out entirely: renders `children` in a plain `<span>`, no AnimatePresence/motion. */
33	  disabled?: boolean;
34	  /** Override the default slide+fade initial/animate/exit values wholesale. */
35	  variants?: SwapTextVariants;
36	  /** Passed through to the inner span (Tailwind callers, or to hook into layout). */
37	  className?: string;
38	}
39	
40	const SwapText = ({
41	  children,
42	  swapKey,
43	  distance = SWAP_TEXT_DEFAULTS.distance,
44	  duration = SWAP_TEXT_DEFAULTS.duration,
45	  transition,
46	  disabled = false,
47	  variants,
48	  className,
49	}: SwapTextProps) => {
50	  const reduce = useReducedMotion();
51	  const key =
52	    swapKey ??
53	    (typeof children === "string" || typeof children === "number" ? String(children) : "static");
54	
55	  if (disabled) {
56	    return <span className={className}>{children}</span>;
57	  }
58	
59	  const initial = variants?.initial ?? { opacity: 0, y: reduce ? 0 : distance };
60	  const animate = variants?.animate ?? { opacity: 1, y: 0 };
61	  const exit = variants?.exit ?? { opacity: 0, y: reduce ? 0 : -distance };
62	
63	  return (
64	    <AnimatePresence mode="wait" initial={false}>
65	      <motion.span
66	        key={key}
67	        className={className}
68	        initial={initial}
69	        animate={animate}
70	        exit={exit}
71	        transition={transition ?? { duration, ease: SWAP_TEXT_DEFAULTS.ease }}
72	        style={{ display: "inline-block" }}
73	      >
74	        {children}
75	      </motion.span>
76	    </AnimatePresence>
77	  );
78	};
79	
80	export default SwapText;
81
